    "description": "The size of the generated image. If not provided, the size of the final input image will be used.  Total number of pixels must be between 512x512 and 2048x2048.",
    "title": "Image Size",
    "anyOf": [
      {
        "$ref": "#/components/schemas/ImageSize"
      },
      {
        "type": "string",
        "enum": [
          "square_hd",
          "square",
          "portrait_4_3",
          "portrait_16_9",
          "landscape_4_3",
          "landscape_16_9"
        ]
      },
      {
        "type": "null"
      }
    ]
  },
  "num_images": {
    "type": "integer",
    "description": "The number of images to generate.",
    "title": "Num Images",
    "default": 1,
    "maximum": 6,
    "minimum": 1
  },
  "seed": {
    "description": "Random seed for reproducibility (0-2147483647).",
    "title": "Seed",
    "anyOf": [
      {
        "type": "integer"
      },
      {
        "type": "null"
      }
    ]
  },
  "output_format": {
    "type": "string",
    "description": "The format of the generated image.",
    "title": "Output Format",
    "default": "png",
    "enum": [
      "jpeg",
      "png",
      "webp"
    ]
  },
  "enable_prompt_expansion": {
    "type": "boolean",
    "description": "Enable LLM prompt optimization for better results.",
    "title": "Enable Prompt Expansion",
    "default": true
  },
  "enable_safety_checker": {
    "type": "boolean",
    "description": "Enable content moderation for input and output.",
    "title": "Enable Safety Checker",
    "default": true
  },
  "prompt": {
    "type": "string",
    "description": "Text prompt describing the desired image. Supports Chinese and English;.",
    "title": "Prompt",
    "examples": [
      "Make this scene summer setting."
    ],
    "minLength": 1
  },
  "sync_mode": {
    "type": "boolean",
    "description": "If `True`, the media will be returned as a data URI and the output data won't be available in the request history.",
    "title": "Sync Mode",
    "default": false
  },
  "negative_prompt": {
    "description": "Content to avoid in the generated image. Max 500 characters.",
    "title": "Negative Prompt",
    "default": "",
    "examples": [
      "low resolution, error, worst quality, low quality, deformed"
    ],
    "anyOf": [
      {
        "maxLength": 500,
        "type": "string"
      },
      {
        "type": "null"
      }
    ]
  },
  "image_urls": {
    "type": "array",
    "items": {
      "type": "string",
      "_fal_ui_field": "image"
    },
    "title": "Image Urls",
    "examples": [
      [
        "https://v3b.fal.media/files/b/0a90b28f/45QiEHyDMwQiB3jFyZ79F_image_00079.png"
      ]
    ],
    "description": "Reference images for editing (1-3 images required). Order matters: reference as 'image 1', 'image 2', 'image 3' in prompt. Resolution: 384-5000px each dimension. Max size: 10MB each. Formats: JPEG, JPG, PNG (no alpha), WEBP."
  }
}

{
  "num_inference_steps": {
    "type": "integer",
    "maximum": 50,
    "default": 28,
    "minimum": 2,
    "description": "The number of inference steps to perform.",
    "title": "Number of Inference Steps"
  },
  "prompt": {
    "type": "string",
    "description": "The prompt to generate an image from.",
    "examples": [
      "A high-quality 3D render of a cute fluffy monster eating a giant donut; the fur simulation is incredibly detailed, the donut glaze is sticky and reflective, bright daylight lighting, shallow depth of field."
    ],
    "title": "Prompt"
  },
  "safety_tolerance": {
    "type": "string",
    "default": "2",
